(()=>{const lang=document.documentElement.lang;const dialog=document.querySelector('.film-dialog');if(dialog){const host=dialog.querySelector('.film-player-host'),caption=dialog.querySelector('.film-player-caption');let opener,previousOverflow='';function close(){dialog.close()}document.querySelectorAll('[data-video-src],[data-drive-id]').forEach(button=>button.addEventListener('click',()=>{opener=button;previousOverflow=document.body.style.overflow;host.replaceChildren();caption.replaceChildren();const title=button.dataset.filmTitle||'Charlot Crea';if(button.dataset.videoSrc){const video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.src=button.dataset.videoSrc;video.setAttribute('aria-label',title);host.append(video);dialog.showModal();video.play().catch(()=>{});}else{const frame=document.createElement('iframe');frame.src='https://drive.google.com/file/d/'+encodeURIComponent(button.dataset.driveId)+'/preview';frame.title=title;frame.allow='autoplay; fullscreen; encrypted-media';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';host.append(frame);dialog.showModal();}caption.append(document.createTextNode(title));if(button.dataset.driveId){const original=document.createElement('a');original.href='https://drive.google.com/file/d/'+encodeURIComponent(button.dataset.driveId)+'/view';original.target='_blank';original.rel='noopener noreferrer';original.textContent=lang==='tr'?'Yeni sekmede aç ↗':'Open in new tab ↗';caption.append(original)}document.body.style.overflow='hidden'}));dialog.querySelector('.film-close').addEventListener('click',close);dialog.addEventListener('close',()=>{host.querySelector('video')?.pause();host.replaceChildren();document.body.style.overflow=previousOverflow;opener?.focus()})}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))}));})();
